package com.thakaan.exposure

import kotlin.math.exp
import kotlin.math.ln
import kotlin.math.pow

/**
 * Universal Thermal Climate Index (Broede et al. 2012 polynomial), generated by AST-transpiling
 * pythermalcomfort's utci polynomial (211 terms: coefficient, powers of Tdb, v, (Tmrt - Tdb), vapour pressure kPa).
 * Reference cases below come from running that library, not from this code.
 *
 * UTCI is a secondary comfort index. It is never used instead of Liljegren WBGT for the heat-stress anchor.
 */
object Utci {
    /** Inputs outside this envelope make the polynomial unreliable, so the answer is null rather than a guess. */
    fun inRange(tdbC: Double, tmrtC: Double, windMs: Double, rhPercent: Double): Boolean =
        tdbC in -50.0..50.0 && (tmrtC - tdbC) in -30.0..70.0 && windMs in 0.5..17.0 && rhPercent in 0.0..100.0

    fun saturationHpa(tdbC: Double): Double {
        val g = doubleArrayOf(-2836.5744, -6028.076559, 19.54263612, -0.02737830188, 0.000016261698, 7.0229056e-10, -1.8680009e-13)
        val tk = tdbC + 273.15
        var es = 2.7150305 * ln(tk)
        for ((i, c) in g.withIndex()) es += c * tk.pow(i - 2)
        return exp(es) * 0.01
    }

    /** Wind is the 10 m wind in m/s; v below 0.5 is clamped up (a calm-air floor, never lower than the model allows). */
    fun compute(tdbC: Double, tmrtC: Double, windMs: Double, rhPercent: Double): Double? {
        val v = if (windMs < 0.5 && windMs >= 0.0) 0.5 else windMs
        if (!inRange(tdbC, tmrtC, v, rhPercent)) return null
        val pa = saturationHpa(tdbC) * (rhPercent / 100.0) / 10.0
        val d = tmrtC - tdbC
        var sum = 0.0
        for (t in TERMS) sum += t[0] * tdbC.pow(t[1]) * v.pow(t[2]) * d.pow(t[3]) * pa.pow(t[4])
        return sum
    }

    /** Heat-stress band label (Bröde thresholds). */
    fun category(utci: Double): String = when {
        utci < 26.0 -> "no heat stress"
        utci < 32.0 -> "moderate heat stress"
        utci < 38.0 -> "strong heat stress"
        utci < 46.0 -> "very strong heat stress"
        else -> "extreme heat stress"
    }

